WITH RecursiveTagCounts AS (
    SELECT
        t.TagName,
        t.Count,
        p.CreationDate::date AS PostDate
    FROM
        Tags t
    LEFT JOIN
        Posts p ON p.Tags LIKE '%' || t.TagName || '%'
    WHERE
        p.PostTypeId = 1 -- questions only
),
UserReputationWindow AS (
    SELECT
        u.Id,
        u.DisplayName,
        u.Reputation,
        u.CreationDate,
        ExaminationDate,
        COALESCE(LAG(u.Reputation) OVER (PARTITION BY OrganizationId ORDER BY u.CreationDate), 0) sent_sup,
        REPLACE(COALESCE(u.WebsiteUrl,''), 'http://','') AS NormalizedUrl,
        LENGTH(COALESCE(u.AboutMe,'')) AS AboutBioLength,
